[MITM]
hostname = hdgateway.zto.com

[Rewrite]
request if ${url} ~= /^https?:\/\/hdgateway\.zto\.com\/getApolloConfig/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/hdgateway\.zto\.com\/track/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/hdgateway\.zto\.com\/getAdInfo/i then reject_dict(200)
request if ${url} ~= /^https?:\/\/hdgateway\.zto\.com\/listJumperShow/i then reject_dict(200)
